/**
 * Claude Intelligence API Routes
 *
 * REST + SSE endpoints for Claude-powered document intelligence:
 * - POST /api/claude/draft — Draft regulatory document sections
 * - POST /api/claude/draft/stream — Stream document drafting (SSE)
 * - POST /api/claude/review — Compliance review
 * - POST /api/claude/gap-analysis — Gap analysis
 * - POST /api/claude/vision — Analyze scanned documents/images
 * - POST /api/claude/batch — Batch draft multiple sections
 * - POST /api/claude/quick — Quick completion (Sonnet, fast)
 * - GET  /api/claude/health — Claude provider health status
 * - GET  /api/claude/models — Available Claude models
 */

import { Router, Request, Response } from 'express';
import { createHash } from 'crypto';
import {
  getAnaDraftingService,
} from '../services/ana/AnaDocumentDraftingService';
import { getGateway } from '../services/ai-gateway/gateway';
import {
  projectModelsForPicker,
  EFFORT_LEVELS,
  DEFAULT_EFFORT,
} from '../services/ai-gateway/effort';
import { serverError } from '../lib/api-response';
import { createScopedLogger } from '../utils/logger';
import {
  classifyGatewayError,
  isGatewayError,
  GATEWAY_ERROR_HTTP_STATUS,
} from '../services/ai-gateway/gateway-error-map';
import { isBatchDraftFailure, type BatchDraftResult } from '../services/ana/batch-draft-result';
import type { DocumentDraftResponse } from '../services/ana/AnaDocumentDraftingService';
import { requestConnectable } from '../db/requestDb.js';
import { loopToolCollector, recordLoopTurn, type LoopToolCall } from '../services/ana/turn-record-loop.js';
import { canonicalJson, openTurnRecorder, writeTurnRecordSafely } from '../services/ana/turn-record.js';
import { resolveOrgId, resolveUserId } from '../types/auth-request.js';

const router = Router();

const logger = createScopedLogger('ana-intelligence');

/**
 * Answer a failed AI request as what it is.
 *
 * Every handler here used to end in `serverError(...)`: HTTP 500, code
 * INTERNAL_ERROR, "Something went wrong while saving batch." A request the
 * gateway refused because no model can hold it, a provider rate limit and a
 * genuine fault were indistinguishable to the client — and the author of a
 * section too large to revise was handed a support reference for a server
 * problem that did not exist. A gateway refusal is answered with its stable
 * code, its HTTP status (413 / 429 / 503) and the gateway's own sentence —
 * which for a size refusal names how big the request is, the largest window
 * available to it, and how much to cut. A fault of ours still goes through
 * serverError, internals withheld.
 */
function failRequest(res: Response, where: string, error: unknown): Response {
  if (isGatewayError(error)) {
    const { code, message } = classifyGatewayError(error);
    logger.warn(`${where}: the AI gateway declined the request`, { code });
    return res.status(GATEWAY_ERROR_HTTP_STATUS[code]).json({ success: false, error: code, message });
  }
  return serverError(res, logger, where, error);
}

/**
 * The caller's organization and user, taken from the authenticated request and
 * nowhere else.
 *
 * This router read `req.organizationId`, which the auth chain does not set on
 * the /api/claude mount, so every call reached the gateway with no tenant: the
 * tenant's AI placement policy (vendors, residency, zero retention) was never
 * applied, usage was not metered to the tenant, and the provenance row below
 * was filed under no organization. /batch also let each request in the BODY
 * name its own organizationId and userId, and preferred them — a caller could
 * draft under another organization's placement policy and bill it. Now the
 * server's identity always wins.
 */
function identityOf(req: Request): { organizationId: number | undefined; userId: number | undefined } {
  return { organizationId: resolveOrgId(req) ?? undefined, userId: resolveUserId(req) ?? undefined };
}

/**
 * Model-governance provenance (decision register #727 item 8): every
 * generation on a regulated-drafting surface writes an append-only audit
 * row recording WHICH pinned model produced WHAT content (sha256 of the
 * output), so any document later saved from this content can be traced
 * back to its model version by hashing it. Fire-and-forget — provenance
 * recording must never fail the drafting request; the dynamic import
 * keeps audit/DB code off this router's load path.
 */
function recordModelProvenance(params: {
  req: Request;
  surface: string;
  model: string | undefined;
  content: string | undefined;
  usage?: { inputTokens?: number; outputTokens?: number };
}): void {
  void (async () => {
    try {
      const { default: auditService } = await import('../services/auditService');
      const { organizationId, userId } = identityOf(params.req);
      await auditService.logAction({
        tenantId: organizationId,
        userId,
        action: 'ai_generation',
        resourceType: 'ai_drafting_surface',
        resourceId: params.surface,
        details: {
          model: params.model || 'unknown',
          contentSha256: params.content
            ? createHash('sha256').update(params.content).digest('hex')
            : null,
          inputTokens: params.usage?.inputTokens ?? null,
          outputTokens: params.usage?.outputTokens ?? null,
        },
      });
    } catch (err: any) {
      console.warn('[Claude Intelligence] model provenance record failed:', err?.message);
    }
  })();
}

// ─────────────────────────────────────────────────────────────────────────────
// Document Drafting
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/draft
 * Draft a regulatory document section.
 */
router.post('/draft', async (req: Request, res: Response) => {
  try {
    const {
      framework,
      submissionType,
      sectionType,
      instructions,
      existingContent,
      projectContext,
      enableThinking,
      thinkingBudget,
      enableTools,
    } = req.body;

    // Either a hardcoded framework OR a registry submission type unlocks authoring.
    if ((!framework && !submissionType) || !sectionType || !instructions) {
      return res.status(400).json({
        error: 'Missing required fields: (framework or submissionType), sectionType, instructions',
      });
    }

    const service = getAnaDraftingService();
    const result = await service.draftDocument({
      framework: framework ?? 'general_regulatory',
      submissionType,
      sectionType,
      instructions,
      existingContent,
      projectContext,
      enableThinking: enableThinking ?? true,
      thinkingBudget,
      enableTools: enableTools ?? true,
      ...identityOf(req),
    });

    recordModelProvenance({
      req,
      surface: 'draft',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });

    res.json({
      success: true,
      data: result,
    });
  } catch (error: any) {
    console.error('[Claude Intelligence] Draft error:', error.message);
    return failRequest(res, 'drafting', error);
  }
});

/**
 * POST /api/claude/draft/stream
 * Stream document drafting via Server-Sent Events.
 */
router.post('/draft/stream', async (req: Request, res: Response) => {
  try {
    const {
      framework,
      submissionType,
      sectionType,
      instructions,
      existingContent,
      projectContext,
      enableThinking,
      thinkingBudget,
      enableTools,
    } = req.body;

    if ((!framework && !submissionType) || !sectionType || !instructions) {
      return res.status(400).json({
        error: 'Missing required fields: (framework or submissionType), sectionType, instructions',
      });
    }

    // Set up SSE headers
    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
      'X-Accel-Buffering': 'no',
    });

    const service = getAnaDraftingService();

    const result = await service.draftDocument({
      framework: framework ?? 'general_regulatory',
      submissionType,
      sectionType,
      instructions,
      existingContent,
      projectContext,
      enableThinking: enableThinking ?? true,
      thinkingBudget,
      enableTools: enableTools ?? true,
      ...identityOf(req),
      onStream: (chunk, metadata) => {
        const event = {
          type: metadata?.type || 'text',
          content: chunk,
          thinking: metadata?.thinkingContent,
        };
        res.write(`data: ${JSON.stringify(event)}\n\n`);
      },
    });

    // Send final event with full response metadata
    recordModelProvenance({
      req,
      surface: 'draft/stream',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });
    res.write(`data: ${JSON.stringify({
      type: 'done',
      model: result.model,
      usage: result.usage,
      cacheHit: result.cacheHit,
      latencyMs: result.latencyMs,
      toolsUsed: result.toolsUsed,
    })}\n\n`);

    res.end();
  } catch (error: any) {
    console.error('[Claude Intelligence] Stream error:', error.message);
    // If headers already sent, send error event
    if (res.headersSent) {
      // The stream is already open, so the failure travels as an event. `error`
      // stays the sentence the stream client renders; `code` is added for a
      // client that branches on it. A gateway refusal carries the gateway's
      // own sentence; anything else is withheld — a driver message is no more
      // stream copy than it is response copy.
      const failure = isGatewayError(error)
        ? classifyGatewayError(error)
        : { code: 'INTERNAL_ERROR', message: 'Drafting failed. The problem has been logged.' };
      if (failure.code === 'INTERNAL_ERROR') {
        logger.error('streaming the draft failed', { err: error?.message });
      }
      res.write(`data: ${JSON.stringify({ type: 'error', code: failure.code, error: failure.message })}\n\n`);
      res.end();
    } else {
      return failRequest(res, 'streaming the draft', error);
    }
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Compliance Review
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/review
 * Run compliance review on document content.
 */
router.post('/review', async (req: Request, res: Response) => {
  try {
    const { content, framework, submissionType, enableThinking } = req.body;

    if (!content || (!framework && !submissionType)) {
      return res.status(400).json({
        error: 'Missing required fields: content, (framework or submissionType)',
      });
    }

    const service = getAnaDraftingService();
    const result = await service.reviewCompliance(content, submissionType ?? framework, {
      enableThinking: enableThinking ?? true,
      ...identityOf(req),
    });

    recordModelProvenance({
      req,
      surface: 'review',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });

    res.json({ success: true, data: result });
  } catch (error: any) {
    console.error('[Claude Intelligence] Review error:', error.message);
    return failRequest(res, 'running the compliance review', error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Gap Analysis
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/gap-analysis
 * Perform gap analysis on a document.
 */
router.post('/gap-analysis', async (req: Request, res: Response) => {
  try {
    const { documentContent, framework, submissionType, targetSections, enableThinking } = req.body;

    if (!documentContent || (!framework && !submissionType) || !targetSections) {
      return res.status(400).json({
        error: 'Missing required fields: documentContent, (framework or submissionType), targetSections',
      });
    }

    const service = getAnaDraftingService();
    const result = await service.analyzeGaps(
      documentContent,
      submissionType ?? framework,
      targetSections,
      {
        enableThinking: enableThinking ?? true,
        ...identityOf(req),
      }
    );

    recordModelProvenance({
      req,
      surface: 'gap-analysis',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });

    res.json({ success: true, data: result });
  } catch (error: any) {
    console.error('[Claude Intelligence] Gap analysis error:', error.message);
    return failRequest(res, 'running the gap analysis', error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Vision (Scanned Document Analysis)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/vision
 * Analyze a scanned document or image.
 */
router.post('/vision', async (req: Request, res: Response) => {
  try {
    const { imageData, mediaType, instructions, framework, enableThinking } = req.body;

    if (!imageData || !mediaType || !instructions) {
      return res.status(400).json({
        error: 'Missing required fields: imageData (base64), mediaType, instructions',
      });
    }

    const service = getAnaDraftingService();
    const result = await service.analyzeImage({
      imageData,
      mediaType,
      instructions,
      framework,
      enableThinking,
      ...identityOf(req),
    });

    recordModelProvenance({
      req,
      surface: 'vision',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });

    res.json({ success: true, data: result });
  } catch (error: any) {
    console.error('[Claude Intelligence] Vision error:', error.message);
    return failRequest(res, 'analyzing the image', error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Batch Operations
// ─────────────────────────────────────────────────────────────────────────────

/**
 * One turn record for a batch: what was asked for, and every draft produced
 * (periodic review 2026-09-28, editor family, the batch-draft accept). Each
 * draft is returned naming the record. The accept (routes/batch-draft-routes.ts)
 * believes a claim that a card's text is AnA's only when this record holds it,
 * and takes the model from here: the one model the drafts report, or none when
 * they report more than one. Never throws; a batch not recorded says so.
 */
async function recordBatchTurn(req: Request, requests: unknown[], results: BatchDraftResult[]) {
  const { organizationId, userId } = identityOf(req);
  const recorder = openTurnRecorder({ orgId: organizationId, userId, typed: canonicalJson(requests), surface: 'api:claude/batch' });
  const drafts: Array<{ title: string; content: string }> = [];
  const models = new Set<string>();
  results.forEach((r, i) => {
    const title = String((requests[i] as { sectionType?: unknown } | undefined)?.sectionType ?? `Section ${i + 1}`);
    if (isBatchDraftFailure(r)) return recorder?.warn(`${title} was not drafted: ${r.message}`);
    drafts.push({ title, content: r.content });
    if (r.model) models.add(r.model);
  });
  recorder?.setModel({ model: models.size === 1 ? [...models][0] : null });
  if (models.size > 1) recorder?.warn(`The drafts were served by more than one model: ${[...models].join(', ')}.`);
  recorder?.setOutputs({ drafts });
  recorder?.warn('This turn ran through the batch drafting door, which reports each section\'s request and its draft but not the messages each model call was sent.');
  const turnRecord = await writeTurnRecordSafely(requestConnectable(req), recorder, drafts.length > 0 ? 'answered' : 'failed', { ipAddress: req.ip, userAgent: req.get('user-agent') ?? undefined });
  return results.map((r) => (isBatchDraftFailure(r) ? r : { ...r, turnRecord }));
}

/**
 * POST /api/claude/batch
 * Batch draft multiple document sections.
 */
router.post('/batch', async (req: Request, res: Response) => {
  try {
    const { requests, concurrency } = req.body;

    if (!requests || !Array.isArray(requests) || requests.length === 0) {
      return res.status(400).json({
        error: 'Missing required field: requests (array of draft requests)',
      });
    }

    if (requests.length > 20) {
      return res.status(400).json({
        error: 'Maximum 20 requests per batch',
      });
    }

    if (requests.some((item: unknown) => item !== null && typeof item === 'object' && Object.hasOwn(item, 'sourceContext'))) {
      return res.status(400).json({
        error: 'UNTRUSTED_SOURCE_CONTEXT',
        message: 'Source context is reserved for admitted server code. Select project sources through AnA before drafting with evidence.',
      });
    }

    const service = getAnaDraftingService();

    // The server's identity on every request; a body-supplied organizationId
    // or userId is overwritten, never preferred.
    const identity = identityOf(req);
    const enrichedRequests = requests.map((r: any) => ({ ...r, ...identity }));

    const results = await service.batchDraft({
      requests: enrichedRequests,
      concurrency: Math.min(concurrency || 3, 5),
    });

    // A section that could not be drafted is a failure RESULT in its own slot
    // (batch-draft-result.ts), never a rejection of the batch: the client reads
    // `results[i].error` per card. The summary is computed over the drafts
    // that exist and COUNTS the ones that do not — an average taken over the
    // failures too would divide by the wrong number and report a latency
    // nobody paid for.
    const drafted = results.filter((r): r is DocumentDraftResponse => !isBatchDraftFailure(r));
    const failed = results.length - drafted.length;
    res.json({
      success: true,
      data: {
        // Each draft names the turn record that holds it; the accept sends that id back.
        results: await recordBatchTurn(req, requests, results),
        summary: {
          total: results.length,
          drafted: drafted.length,
          failed,
          totalInputTokens: drafted.reduce((s, r) => s + r.usage.inputTokens, 0),
          totalOutputTokens: drafted.reduce((s, r) => s + r.usage.outputTokens, 0),
          totalCostUsd: drafted.reduce((s, r) => s + r.usage.estimatedCostUsd, 0),
          avgLatencyMs: drafted.length > 0
            ? drafted.reduce((s, r) => s + r.latencyMs, 0) / drafted.length
            : 0,
        },
      },
    });
    // Provenance is recorded for content that exists; a failure produced none.
    for (const r of drafted) {
      recordModelProvenance({
        req,
        surface: 'batch',
        model: r.model,
        content: r.content,
        usage: r.usage,
      });
    }
  } catch (error: any) {
    console.error('[Claude Intelligence] Batch error:', error.message);
    return failRequest(res, 'drafting the batch', error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Quick Completion
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/quick
 * Quick completion using Claude Sonnet (fast, cost-effective). With a
 * `framework` it is regulatory drafting and is governed as such: an approved
 * model, and in production a PQ-passed one (quickComplete).
 */
router.post('/quick', async (req: Request, res: Response) => {
  try {
    const { prompt, framework, maxTokens } = req.body;

    if (!prompt) {
      return res.status(400).json({ error: 'Missing required field: prompt' });
    }

    const service = getAnaDraftingService();
    const result = await service.quickComplete(prompt, {
      framework,
      maxTokens,
      ...identityOf(req),
    });

    recordModelProvenance({
      req,
      surface: 'quick',
      // The model the gateway served. Until 2026-09-23 this was the literal
      // 'claude-sonnet-4-6' — a registry entry quickComplete does not even pin —
      // written into the sealed audit log whatever had answered.
      model: result.model,
      content: result.content,
    });

    res.json({ success: true, data: { content: result.content } });
  } catch (error: any) {
    console.error('[Claude Intelligence] Quick error:', error.message);
    return failRequest(res, 'completing the prompt', error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Agentic Loop (multi-turn tool use)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * POST /api/claude/agent
 * Run a multi-turn agentic loop with Claude tool use.
 * Claude can search evidence, look up regulations, and generate citations autonomously.
 */
router.post('/agent', async (req: Request, res: Response) => {
  // The turn is recorded whichever way it ends (services/ana/turn-record-loop.ts).
  let recordTurn: ((outcome: 'answered' | 'failed', response?: unknown, error?: unknown) => ReturnType<typeof recordLoopTurn>) | null = null;
  try {
    const { prompt, framework, systemPrompt, maxRounds, enableThinking } = req.body;

    if (!prompt) {
      return res.status(400).json({ error: 'Missing required field: prompt' });
    }

    const { executeAgenticLoop } = await import(
      '../services/ana/AnaToolExecutor'
    );
    const { DOCUMENT_DRAFTING_TOOLS } = await import(
      '../services/ana/AnaToolDefinitions'
    );

    // Build system prompt
    const system = systemPrompt || 'You are a regulatory affairs expert with access to clinical trial databases, FDA guidance, and literature search tools. Use the available tools to research and provide evidence-based answers.';
    /* Framework context is embedded directly in the system prompt below;
       the dynamic AnaDocumentDraftingService import was unused dead code
       and was removed. */

    const messages = [
      { role: 'system' as const, content: system },
      { role: 'user' as const, content: prompt },
    ];
    // identityOf: see above. This door ran its tools with no tenant and — the
    // turn record showed it on first run — could not file the turn under one.
    const { organizationId, userId } = identityOf(req);
    const collected = loopToolCollector();
    recordTurn = (outcome, response, error) =>
      recordLoopTurn(
        requestConnectable(req),
        {
          orgId: organizationId,
          userId,
          surface: 'api:claude/agent',
          typed: String(prompt),
          messages,
          calls: collected.calls as LoopToolCall[],
          response: response as Parameters<typeof recordLoopTurn>[1]['response'],
          outcome,
          error,
        },
        { ipAddress: req.ip, userAgent: req.get('user-agent') ?? undefined },
      );

    const result = await executeAgenticLoop(
      {
        taskType: 'document_drafting',
        messages,
        provider: 'anthropic',
        // Registry alias: resolves to the current Opus. A pinned wire version
        // stops matching on the next bump and silently falls through to normal
        // routing.
        model: 'claude-opus-4',
        maxTokens: 8192,
        tools: DOCUMENT_DRAFTING_TOOLS,
        toolChoice: 'auto',
        thinking: enableThinking ? { enabled: true, budgetTokens: 15000 } : undefined,
        promptCache: { enabled: true, type: 'ephemeral' },
        organizationId,
        userId,
        callerModule: 'ana-intelligence/agent',
      },
      {
        maxRounds: maxRounds || 5,
        onToolExecution: (toolName, input, result) => {
          console.log(`[Claude Agent] Tool: ${toolName}`, Object.keys(input));
          collected.onToolExecution(toolName, input, result);
        },
      }
    );

    recordModelProvenance({
      req,
      surface: 'agent',
      model: result.model,
      content: result.content,
      usage: result.usage,
    });
    const turnRecord = await recordTurn('answered', result);

    res.json({
      success: true,
      data: {
        content: result.content,
        thinking: result.thinking,
        toolsUsed: result.toolUses?.map(t => t.name),
        model: result.model,
        usage: result.usage,
        latencyMs: result.latencyMs,
        turnRecord,
      },
    });
  } catch (error: any) {
    console.error('[Claude Intelligence] Agent error:', error.message);
    if (recordTurn) await recordTurn('failed', undefined, error);
    return failRequest(res, 'running the agent', error);
  }
});

/**
 * GET /api/claude/tools
 * List available tools and their registration status.
 */
router.get('/tools', async (_req: Request, res: Response) => {
  const { getAvailableTools } = await import(
    '../services/ana/AnaToolExecutor'
  );
  res.json({ success: true, data: { tools: getAvailableTools() } });
});

// ─────────────────────────────────────────────────────────────────────────────
// Health & Info
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /api/claude/health
 * Claude provider health status.
 */
router.get('/health', (_req: Request, res: Response) => {
  const gateway = getGateway();
  const allHealth = gateway.getProviderHealth();
  const anthropicHealth = allHealth.find(h => h.provider === 'anthropic');
  const enabledProviders = gateway.getEnabledProviders();

  res.json({
    success: true,
    data: {
      anthropic: anthropicHealth || { provider: 'anthropic', healthy: false, consecutiveFailures: 0 },
      isEnabled: enabledProviders.includes('anthropic'),
      isDeterministic: gateway.isDeterministic(),
      allProviders: allHealth,
    },
  });
});

/**
 * GET /api/claude/models
 * Available models for the AnA Composer's model/effort picker.
 *
 * Projected live from the gateway's model registry (gated on API-key presence)
 * rather than a static list, so the picker only ever offers models the gateway
 * can actually route to. Each option carries a derived `label` and
 * `recommendedEffort` (neither exists on the raw ModelConfig). The effort
 * controls (`effortLevels` + `defaultEffort`) and the legacy `frameworks` array
 * are preserved alongside the `{ success, data }` envelope.
 */
router.get('/models', (_req: Request, res: Response) => {
  const models = projectModelsForPicker(getGateway().getModels());
  res.json({
    success: true,
    data: {
      models,
      effortLevels: EFFORT_LEVELS,
      defaultEffort: DEFAULT_EFFORT,
      frameworks: [
        'fda_510k',
        'fda_pma',
        'eu_mdr',
        'ich_clinical',
        'cer_clinical_evaluation',
        'general_regulatory',
      ],
    },
  });
});

export default router;

/**
 * Shared gateway-error classifier.
 *
 * Maps an error thrown by the AI gateway to a stable {code, message} the route
 * layer turns into an HTTP status — so rate-limit / token-limit / policy /
 * provider-unavailable are distinguished instead of being flattened to one 503.
 * Never leaks a raw provider error string to the client.
 *
 * @module server/services/ai-gateway/gateway-error-map
 */

import {
  GatewayPolicyError,
  ModelNotApprovedError,
  GatewayNoProviderError,
  GatewayAllProvidersFailedError,
} from './gateway';
import { GatewayContextWindowError } from './context-budget';
import { isTenantPlacementRefusal } from './gateway-outcome';
import { NO_PQ_QUALIFIED_MODEL } from './model-governance';

export type GatewayErrorCode =
  | 'SOURCE_CONTEXT_UNAVAILABLE'
  | 'PLACEMENT_REFUSED'
  | 'MODEL_NOT_QUALIFIED'
  | 'RATE_LIMITED'
  | 'OVERLOADED'
  | 'TOKEN_LIMIT_EXCEEDED'
  | 'PROVIDER_UNAVAILABLE'
  | 'INVALID_AI_RESPONSE';

export interface ClassifiedGatewayError {
  code: GatewayErrorCode;
  message: string;
}

/**
 * The HTTP status each code answers with. One table, exported, so a route that
 * calls the gateway directly does not grow its own copy — the copies in
 * submissions.ts and ectd-documents.ts predate this export and agree with it.
 */
export const GATEWAY_ERROR_HTTP_STATUS: Readonly<Record<GatewayErrorCode, number>> = {
  SOURCE_CONTEXT_UNAVAILABLE: 409,
  // Not an outage: the organization's own policy excludes every lane that
  // could serve the request, and retrying cannot change that.
  PLACEMENT_REFUSED: 403,
  // Not an outage either: model governance refused every model that could
  // serve — none PQ-qualified for production drafting, none approved for the
  // high-risk task, or the one named is no approved entry. Nothing changes on
  // a retry; it changes when governance does (track GW review [5]/[23]).
  MODEL_NOT_QUALIFIED: 403,
  RATE_LIMITED: 429,
  OVERLOADED: 503,
  TOKEN_LIMIT_EXCEEDED: 413,
  PROVIDER_UNAVAILABLE: 503,
  INVALID_AI_RESPONSE: 502,
};

/**
 * True for an error the gateway itself raised. A route uses this to decide
 * between "answer with the classified code and status" and "this is a fault of
 * ours — log it and answer 500". Without the distinction every AI failure is a
 * 500, and a too-large input is indistinguishable from a crash.
 */
export function isGatewayError(err: unknown): boolean {
  return (
    err instanceof GatewayContextWindowError ||
    err instanceof GatewayAllProvidersFailedError ||
    err instanceof GatewayNoProviderError ||
    err instanceof GatewayPolicyError
  );
}

/** Classify a thrown gateway/parse error into a stable code + safe message. */
export function classifyGatewayError(err: unknown): ClassifiedGatewayError {
  if (err instanceof SyntaxError) {
    return { code: 'INVALID_AI_RESPONSE', message: 'The AI response was not valid JSON.' };
  }
  // Refused by the gateway's own admission before any provider was called. The
  // message is gateway-authored (size, ceiling, how much to cut) — not a
  // provider string — so it is safe to hand to the author as written.
  if (err instanceof GatewayContextWindowError) {
    return { code: 'TOKEN_LIMIT_EXCEEDED', message: err.message };
  }
  if (err instanceof GatewayNoProviderError) {
    return { code: 'PROVIDER_UNAVAILABLE', message: 'No AI provider is available to handle this request.' };
  }
  const refusal = classifyPolicyRefusal(err);
  if (refusal) return refusal;
  if (err instanceof GatewayAllProvidersFailedError) {
    const msg = err.message || '';
    // 529 = Anthropic "Overloaded" (and generic provider overload/503). Distinct
    // from a 429 rate-limit: it is transient back-pressure, retried with backoff
    // in the gateway, and surfaced as a clean "retry shortly" rather than a fault.
    if (/\b529\b|overloaded/i.test(msg)) {
      return { code: 'OVERLOADED', message: 'The AI provider is overloaded right now. Please retry in a moment.' };
    }
    if (/429|rate.?limit/i.test(msg)) {
      return { code: 'RATE_LIMITED', message: 'The AI provider is rate limiting requests. Try again shortly.' };
    }
    if (/token|context length|max.?tokens/i.test(msg)) {
      return { code: 'TOKEN_LIMIT_EXCEEDED', message: 'The input is too large for a single AI request.' };
    }
    return { code: 'PROVIDER_UNAVAILABLE', message: 'The AI provider is temporarily unavailable.' };
  }
  return { code: 'PROVIDER_UNAVAILABLE', message: 'The AI request could not be completed.' };
}

/**
 * A gateway policy refusal, classified by what it refused. Null for anything
 * that is not one.
 */
function classifyPolicyRefusal(err: unknown): ClassifiedGatewayError | null {
  if (err instanceof GatewayPolicyError && (err as { code?: unknown }).code === 'SOURCE_CONTEXT_UNAVAILABLE') {
    return { code: 'SOURCE_CONTEXT_UNAVAILABLE', message: 'Selected project sources changed or are no longer available. Check project access and current source versions before retrying this section.' };
  }
  const governance = classifyModelGovernanceRefusal(err);
  if (governance) return governance;
  // Before the general policy branch: it is a GatewayPolicyError subclass, and
  // "blocked by AI gateway policy" would tell the author nothing they can act on.
  //
  // Neither message says "try again shortly". Until 2026-09-24 both did, and it
  // was false: this refusal is configuration, not load, and on an OpenAI-only
  // deployment (every approvedForHighRisk model is Claude) it answered every
  // draft the same way forever (U3a). /readyz now reports that posture as
  // ana 'no_high_risk_model'; this is what the author sees if it serves anyway.
  if (err instanceof ModelNotApprovedError) {
    // `reason` is read defensively: route tests mock this class bare, and a
    // refusal without one is treated as the configuration case.
    if ((err as { reason?: unknown }).reason === 'explicit') {
      return {
        code: 'PROVIDER_UNAVAILABLE',
        message:
          'The model requested is not approved for regulatory drafting and review, so this ' +
          'request was not sent to it.',
      };
    }
    return {
      code: 'MODEL_NOT_QUALIFIED',
      message:
        'No model approved for regulatory drafting and review is configured on this deployment ' +
        'for this request, so it was not sent to one that is not approved for it. Retrying will ' +
        'not change this; an administrator needs to enable an approved model.',
    };
  }
  if (err instanceof GatewayPolicyError && (err as { code?: unknown }).code === 'RATE_LIMIT_EXCEEDED') {
    const scope = (err as { rateLimit?: { scope?: unknown } }).rateLimit?.scope;
    return {
      code: 'RATE_LIMITED',
      message:
        scope === 'user'
          ? 'Too many requests from you in the last minute. Wait a minute and try again.'
          : 'Too many requests for your organization in the last minute. Wait a minute and try again.',
    };
  }
  // Matched by its code, not `instanceof MediaNotCarriedError`: route tests mock
  // the gateway module with a hand-listed set of error classes, and an
  // `instanceof` against a class the mock omits throws — which turned every
  // classified refusal on those routes into a 500 (authoringAiDraftNoProvider).
  if (err instanceof GatewayPolicyError && (err as { code?: unknown }).code === 'MEDIA_NOT_CARRIED') {
    return {
      code: 'PROVIDER_UNAVAILABLE',
      message:
        'No model that can read the attached file is available right now, so the request was not ' +
        'answered without it. Try again shortly.',
    };
  }
  // The organization's placement policy excludes every lane. The gateway's
  // message names the reason and no content, so it is safe to show as written.
  if (isTenantPlacementRefusal(err)) {
    return { code: 'PLACEMENT_REFUSED', message: err.message };
  }
  if (err instanceof GatewayPolicyError && (err as { code?: unknown }).code === 'FILE_REFERENCE_NOT_CARRIED') {
    return {
      code: 'PROVIDER_UNAVAILABLE',
      message:
        'The document was referenced by an Anthropic file id, which only first-party Anthropic can read, ' +
        'so the request was not answered without it. Attach the document itself.',
    };
  }
  if (err instanceof GatewayPolicyError) {
    return { code: 'PROVIDER_UNAVAILABLE', message: 'This request was blocked by AI gateway policy.' };
  }
  return null;
}

/**
 * The two model-governance refusals ADR-0015 added, matched by code (the
 * reason given above for MEDIA_NOT_CARRIED). Null for anything else. Both are
 * MODEL_NOT_QUALIFIED at 403: a governance decision, not an outage, so no
 * "try again shortly" and no 5xx on a dashboard (track GW review [5]/[23]).
 *
 * - MODEL_NOT_PQ_QUALIFIED: production high-risk drafting with no PQ-passed
 *   model. ADR-0015 §3 says what the person is told, in these words.
 * - MODEL_NOT_GOVERNED: the request named a model the platform does not have
 *   (`unknown-model`); or the only model that could serve is not an approved
 *   entry (`no-entry`), or, in production, pins no concrete artifact
 *   (`nominal-pin`).
 */
function classifyModelGovernanceRefusal(err: unknown): ClassifiedGatewayError | null {
  if (!(err instanceof GatewayPolicyError)) return null;
  const { code, reason } = err as { code?: unknown; reason?: unknown };
  if (code === 'MODEL_NOT_PQ_QUALIFIED') return { code: 'MODEL_NOT_QUALIFIED', message: NO_PQ_QUALIFIED_MODEL };
  if (code !== 'MODEL_NOT_GOVERNED') return null;
  return { code: 'MODEL_NOT_QUALIFIED', message: MODEL_NOT_GOVERNED_COPY[String(reason)] ?? MODEL_NOT_GOVERNED_COPY['no-entry'] };
}

const MODEL_NOT_GOVERNED_COPY: Readonly<Record<string, string>> = {
  'unknown-model': 'This request was not sent: it named a model this platform does not have.',
  'nominal-pin':
    'This request was not sent: the only model that could serve it is not approved for use in this environment.',
  'no-entry': 'This request was not sent: the model that would have served it is not an approved model.',
};
